// @category GFZ
import ghidra.app.script.GhidraScript;import ghidra.program.model.listing.*;import ghidra.program.model.address.*;import ghidra.program.model.mem.Memory;import ghidra.program.model.symbol.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;
public class DumpUnresolvedStructure extends GhidraScript{
 static boolean pref(Function f,String p){for(FunctionTag t:f.getTags())if(t.getName().startsWith(p))return true;return false;}static boolean tag(Function f,String n){for(FunctionTag t:f.getTags())if(t.getName().equals(n))return true;return false;}static String esc(String s){return s==null?"":s.replace("\\","\\\\").replace("\t","\\t").replace("\n","\\n").replace("\r","");}static String hex(byte[]b){StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format("%02x",x&255));return s.toString();}
 static String bh(Function f,Memory m)throws Exception{MessageDigest md=MessageDigest.getInstance("SHA-256");AddressRangeIterator it=f.getBody().getAddressRanges();byte[]buf=new byte[4096];while(it.hasNext()){AddressRange r=it.next();for(long v:new long[]{r.getMinAddress().getOffset(),r.getMaxAddress().getOffset()})for(int sh=56;sh>=0;sh-=8)md.update((byte)(v>>>sh));long rem=r.getLength();Address p=r.getMinAddress();while(rem>0){int n=(int)Math.min(buf.length,rem);int g=m.getBytes(p,buf,0,n);if(g!=n)throw new IOException();md.update(buf,0,n);p=p.add(n);rem-=n;}}return hex(md.digest());}
 public void run()throws Exception{String[]a=getScriptArgs();if(a.length!=1)throw new IllegalArgumentException("out.tsv");FunctionManager fm=currentProgram.getFunctionManager();Listing li=currentProgram.getListing();Memory mem=currentProgram.getMemory();int n=0;try(PrintWriter w=new PrintWriter(new OutputStreamWriter(new FileOutputStream(a[0]),StandardCharsets.UTF_8))){w.println("entry\tname\tsource\tbody_bytes\tinstruction_count\tbody_sha256\tfirst_mnemonic\tlast_mnemonic\tlast_flow_type\tlast_flows\tcalled_functions\tcomment");FunctionIterator fi=fm.getFunctions(true);while(fi.hasNext()){Function f=fi.next();if(f.isExternal()||pref(f,"GFZ.V120.PrimaryOwner.")||tag(f,"GFZ.V120.FinalNoPrimaryOwner")||pref(f,"GFZ.V121.CodeDomain."))continue;n++;InstructionIterator ii=li.getInstructions(f.getBody(),true);Instruction first=null,last=null;int ic=0;while(ii.hasNext()){Instruction x=ii.next();if(first==null)first=x;last=x;ic++;}StringBuilder fl=new StringBuilder();if(last!=null)for(Address x:last.getFlows()){if(fl.length()>0)fl.append(',');Function t=fm.getFunctionAt(x);fl.append(String.format("%08X",x.getOffset())).append('[').append(t==null?"":esc(t.getName())).append(']');}ArrayList<Function> cs=new ArrayList<>(f.getCalledFunctions(monitor));cs.sort(Comparator.comparingLong(x->x.getEntryPoint().getOffset()));StringBuilder cb=new StringBuilder();for(Function t:cs){if(cb.length()>0)cb.append(',');cb.append(String.format("%08X",t.getEntryPoint().getOffset())).append('[').append(esc(t.getName())).append(']');}w.printf("%08X\t%s\t%s\t%d\t%d\t%s\t%s\t%s\t%s\t%s\t%s\t%s%n",f.getEntryPoint().getOffset(),esc(f.getName()),f.getSymbol().getSource(),f.getBody().getNumAddresses(),ic,bh(f,mem),first==null?"":first.getMnemonicString(),last==null?"":last.getMnemonicString(),last==null?"":last.getFlowType(),fl,cb,esc(f.getComment()));}}println("UNRESOLVED_STRUCTURE_DUMP_PASS total="+n);}
}
